 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM slo_budget_state WHERE evaluated_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-4 hours'')) < 27 THEN ''fewer than 27 surfaces evaluated in 4 hours'' WHEN COALESCE((SELECT value FROM ops_config WHERE key = ''slo_merge_lane''), ''absent'') <> ''on'' THEN ''merge lane gate is not on'' WHEN COALESCE((SELECT last_value FROM metric_registry WHERE metric = ''postmortem_coverage''), ''0'') <> ''1'' THEN ''postmortem_coverage is not 1'' ELSE ''ok'' END AS observed',
